import xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for sheet in ['sheet4.xml','sheet5.xml','sheet6.xml','sheet7.xml']:
    print('SHEET', sheet)
    tree=ET.parse('xl/worksheets/'+sheet)
    root=tree.getroot()
    # map cells by ref, parse value and formula
    cells={}
    for c in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
        ref=c.attrib.get('r')
        t=c.attrib.get('t')
        v=None; f=None
        for child in c:
            tag=child.tag.split('}')[1]
            if tag=='v':
                v=child.text
            elif tag=='f':
                f=child.text
        cells[ref]=(t,v,f)
    # print specific refs
    for ref in ['K3','P8','P9','P10','P11','P12','P13','P14','P15']:
        print(ref, cells.get(ref))
    # find formulas containing / and print with refs
